import pandas as pd
import io

def convert_df_to_csv(df):
    """
    Converts DataFrame to CSV for download.
    """
    return df.to_csv(index=False).encode('utf-8')

def generate_eda_report(df, eda_analyzer, preprocessor):
    """
    Generates a textual report of the EDA findings.
    """
    summary = preprocessor.get_summary()
    stats = eda_analyzer.get_descriptive_stats()
    insights = eda_analyzer.get_smart_insights()
    
    report = f"""
# 📊 automated EDA Report
**Generated by Master Data Viz Platform**

---

## 1. Dataset Overview
- **Rows:** {summary['rows']}
- **Columns:** {summary['cols']}
- **Missing Values:** {summary['missing_cells']} ({summary['missing_percent']:.2f}%)
- **Duplicates:** {summary['duplicates']}
- **Memory Usage:** {summary['memory_usage']}

## 2. Smart Insights
"""
    if insights:
        for insight in insights:
            report += f"- {insight}\n"
    else:
        report += "- No critical issues detected.\n"
        
    report += "\n## 3. Statistical Summary\n"
    report += stats.to_markdown()
    
    return report
